notes.back:
// Why: The third argument of JSON.stringify is the indentation. Stringifying the text
// itself (without parsing) just wraps it in quotes.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/JSON/stringify
function prettyJson(text) {
  return JSON.stringify(JSON.parse(text), null, 2);
}

